// unmarshalPollQuestionRequestBodyToVotingPollQuestion builds a value of type
// *voting.PollQuestion from a value of type *PollQuestionRequestBody.
func unmarshalPollQuestionRequestBodyToVotingPollQuestion(v *PollQuestionRequestBody) *voting.PollQuestion {
	res := &voting.PollQuestion{
		QuestionID: v.QuestionID,
		Prompt:     *v.Prompt,
		Type:       *v.Type,
	}
	res.Choices = make([]*voting.PollChoice, len(v.Choices))
	for i, val := range v.Choices {
		if val == nil {
			res.Choices[i] = nil
			continue
		}
		res.Choices[i] = unmarshalPollChoiceRequestBodyToVotingPollChoice(val)
	}

	return res
}

// unmarshalPollChoiceRequestBodyToVotingPollChoice builds a value of type
// *voting.PollChoice from a value of type *PollChoiceRequestBody.
func unmarshalPollChoiceRequestBodyToVotingPollChoice(v *PollChoiceRequestBody) *voting.PollChoice {
	res := &voting.PollChoice{
		ChoiceID:   v.ChoiceID,
		ChoiceText: *v.ChoiceText,
	}

	return res
}

