// marshalVotingPollQuestionToPollQuestionResponseBody builds a value of type
// *PollQuestionResponseBody from a value of type *voting.PollQuestion.
func marshalVotingPollQuestionToPollQuestionResponseBody(v *voting.PollQuestion) *PollQuestionResponseBody {
	if v == nil {
		return nil
	}
	res := &PollQuestionResponseBody{
		QuestionID: v.QuestionID,
		Prompt:     v.Prompt,
		Type:       v.Type,
	}
	if v.Choices != nil {
		res.Choices = make([]*PollChoiceResponseBody, len(v.Choices))
		for i, val := range v.Choices {
			if val == nil {
				res.Choices[i] = nil
				continue
			}
			res.Choices[i] = marshalVotingPollChoiceToPollChoiceResponseBody(val)
		}
	} else {
		res.Choices = []*PollChoiceResponseBody{}
	}

	return res
}

